import{_ as t}from"./chunks/the-zeros-didnt-move.DDtwsDT4.js";import{_ as s,o as a,c as i,aa as r}from"./chunks/framework.CuTukyzC.js";import"./chunks/theme.jdWPvDJU.js";const f=JSON.parse(`{"title":"The editor tripled. The zeros didn't move.","description":"Three days after we measured Invar at 26,000 lines, it passed 69,000 — 396 commits in three days, six new organs, a multi-provider agent harness. Every discipline metric we published held. A follow-up with the greps re-run.","frontmatter":{"title":"The editor tripled. The zeros didn't move.","description":"Three days after we measured Invar at 26,000 lines, it passed 69,000 — 396 commits in three days, six new organs, a multi-provider agent harness. Every discipline metric we published held. A follow-up with the greps re-run.","date":"2026-07"},"headers":[],"relativePath":"blog/the-zeros-didnt-move.md","filePath":"blog/the-zeros-didnt-move.md","lastUpdated":1786402255000}`),o={name:"blog/the-zeros-didnt-move.md"};function n(d,e,h,l,c,g){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="the-editor-tripled-the-zeros-didn-t-move" tabindex="-1">The editor tripled. The zeros didn&#39;t move. <a class="header-anchor" href="#the-editor-tripled-the-zeros-didn-t-move" aria-label="Permalink to &quot;The editor tripled. The zeros didn&#39;t move.&quot;">​</a></h1><p><img src="'+t+'" alt="The editor tripled. The zeros didn&#39;t move."></p><p>Three days ago we published <a href="/blog/agents-built-an-editor">measurements of Invar</a> — the terminal IDE that AI agents build under written contracts and a mechanical referee: 25,890 lines, 153 files, 292 commits, zero cycle-breaking workarounds, one <code>computed()</code>.</p><p>The fair skeptical response was: <em>sure — at 26,000 lines. Discipline is cheap when the codebase is young. Come back when it&#39;s big.</em></p><p>It took three days to get big. <strong>396 commits later</strong> (158 of them in one 24-hour stretch), Invar stands at <strong>68,936 lines of TypeScript across 390 files</strong> — 49,393 of source, 19,543 of tests — with six new subsystems, including the <a href="/blog/introducing-invar">native agent harness</a> with four provider integrations and a text-to-speech narration engine. The codebase grew 2.7× in the time it takes most teams to review one pull request.</p><p>So we re-ran every grep from the first post, on the tripled animal. All counts measured 2026-07-26, reproducible from <a href="https://github.com/infinite-system/invar" target="_blank" rel="noreferrer">the repository</a>.</p><h2 id="the-re-run" tabindex="-1">The re-run <a class="header-anchor" href="#the-re-run" aria-label="Permalink to &quot;The re-run&quot;">​</a></h2><table tabindex="0"><thead><tr><th>discipline metric</th><th style="text-align:right;">at 26k lines</th><th style="text-align:right;">at 69k lines</th></tr></thead><tbody><tr><td>cycle-breaking workarounds (lazy imports, &quot;breaks cycle&quot; files)</td><td style="text-align:right;">0</td><td style="text-align:right;"><strong>0</strong></td></tr><tr><td>memoization calls (<code>useMemo</code>/<code>useCallback</code>/equivalents)</td><td style="text-align:right;">0</td><td style="text-align:right;"><strong>0</strong></td></tr><tr><td>lint suppressions (<code>eslint-disable</code>)</td><td style="text-align:right;">—</td><td style="text-align:right;"><strong>0</strong></td></tr><tr><td>type suppressions (<code>@ts-ignore</code>/<code>@ts-expect-error</code>)</td><td style="text-align:right;">—</td><td style="text-align:right;"><strong>1</strong></td></tr><tr><td><code>computed()</code> in the entire codebase</td><td style="text-align:right;">1</td><td style="text-align:right;"><strong>2</strong></td></tr><tr><td>multi-hop object-graph call sites (<code>workspaceSet.active…</code>)</td><td style="text-align:right;">75</td><td style="text-align:right;"><strong>239</strong></td></tr><tr><td>colocated invariants contracts</td><td style="text-align:right;">14</td><td style="text-align:right;"><strong>20</strong> (7,053 lines)</td></tr><tr><td>tests</td><td style="text-align:right;">384</td><td style="text-align:right;"><strong>1,371</strong> (16,087 assertions, zero failing)</td></tr></tbody></table><p>Three of these numbers deserve their footnotes, because the footnotes are the point.</p><p><strong>The one type suppression</strong> is in a <em>test</em> — a deliberate <code>@ts-expect-error</code> asserting that the type system <strong>rejects</strong> an unkeyed read it must reject. It is not a suppression; it is a negative type test. The single exception in 69,000 lines exists to verify a rule.</p><p><strong>The second <code>computed()</code></strong> follows the same doctrine as <a href="/blog/agents-built-an-editor">the first</a>: a revision-fold cache on a pane&#39;s render version — document-sized work reused across frequent repaints, opted into surgically. Derivation caches grew from one to two while the codebase grew by 43,000 lines. Everything else remains <a href="/blog/computed-is-a-cache">plain getters</a>.</p><p><strong>The 239 deep chains</strong> are the <a href="/blog/the-object-graph-they-took">object graph</a> claim, stress-tested: multi-hop navigation more than tripled alongside the code, written by agents that have still never once been bitten by initialization order. Per-edge immunity is scale-invariant — that was the theory; this is the third data point on the curve.</p><h2 id="what-the-growth-actually-was" tabindex="-1">What the growth actually was <a class="header-anchor" href="#what-the-growth-actually-was" aria-label="Permalink to &quot;What the growth actually was&quot;">​</a></h2><p>Not padding — organs. Since the first measurement, the fleet shipped the native agent pane (session, transcript projection with search, composer, permission membrane), <strong>four agent provider integrations</strong> — Claude over the CLI&#39;s structured event stream and over the SDK, Codex two ways — behind one backend seam with a registry, plus two scripted doubles that let the entire harness verify with no network and no API key. A narration module speaks agent responses through a swappable text-to-speech seam. Image preview renders pictures in the terminal. Search, navigation, and diagnostics became modules. Each arrived with its invariants contract, mirroring the module before it.</p><p>One seam shape, applied again and again — the pattern the <a href="/blog/agents-built-an-editor">first post</a> called an agent-economics win, now measured at <strong>94 <code>Static()</code> seams and 61 <code>Reactive()</code> classes</strong>.</p><h2 id="the-referee-debugged-itself" tabindex="-1">The referee debugged itself <a class="header-anchor" href="#the-referee-debugged-itself" aria-label="Permalink to &quot;The referee debugged itself&quot;">​</a></h2><p>The most instructive artifact of the three days isn&#39;t a feature. Mid sprint, the fleet ran a reliability census on its own merge gate: pulled every gate log on disk — <strong>121 runs, 97 green, 33 rescued retries</strong> — and instead of shipping past the flakes, taxonomized them. Four fragility classes fell out: clock-bound absence windows, vacuous predicates, bare sleeps, and pipe backpressure.</p><p>Then came the reduction. All four classes are <strong>one defect in different costumes: a wait that is not a condition</strong> — a test that pauses instead of observing the state it is about to assert. The fix was doctrinal, not case-by-case: every wait in the harness must be a predicate the pre-action state cannot satisfy.</p><p>And the fleet drew a meta-lesson worth quoting verbatim, because it is the whole contracts philosophy compressed:</p><blockquote><p>An invariant whose positive content is right but whose impossibility set is narrow protects nothing — the mistakes it fails to forbid are the ones people make.</p></blockquote><p>The gate&#39;s existing rule had banned one wrong shape of waiting; the two shapes it didn&#39;t name were both written. So the rule&#39;s <em>negative space</em> was widened to forbid all three, with the legitimate exceptions named. A test-reliability bug became a sharper law. That is what it looks like when the referee is subject to its own regime.</p><p>The verification apparatus is now <strong>39,493 lines</strong> — the smokes, drivers, and gate approaching the size of the source they verify. A ratio like that is usually found in avionics. Here it is what lets 158 commits land in a day without a human reading most of them.</p><h2 id="what-this-settles" tabindex="-1">What this settles <a class="header-anchor" href="#what-this-settles" aria-label="Permalink to &quot;What this settles&quot;">​</a></h2><p>The first post argued that agents are stochastic rule-followers, so <strong>discipline-based safety degrades with scale while construction-based safety doesn&#39;t</strong>. That was one measurement at one size. Now there are two sizes, 2.7× apart, and the discipline metrics are flat: the zeros held, the exceptions stayed countable on one hand, and each exception carries its justification in writing.</p><p>Vigilance dilutes as lines multiply — that is arithmetic. What doesn&#39;t dilute is structure: cycles that cannot manifest, methods that cannot unbind, waits that cannot pass vacuously, changes that cannot merge unverified. Invar&#39;s velocity is not the interesting number. Interesting is that <strong>velocity and drift finally decoupled</strong> — the speed limit is the referee, not the typist.</p><p>The greps are one clone away. Run them at whatever size the editor has reached by the time you read this — that&#39;s the experiment, and so far it only goes one way.</p>',26)])])}const b=s(o,[["render",n]]);export{f as __pageData,b as default};
